"use client"

import { useEffect, useId, useRef, useState } from "react"
import { createPortal } from "react-dom"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { AnimatePresence, m } from "motion/react"
import { usePrefersReducedMotion } from "@/lib/use-reduced-motion"
import { ArrowUpRight, ChevronDown, Handshake, LogIn, Menu, X } from "lucide-react"
import { Logo } from "./Logo"
import { cn } from "@/lib/utils"
import { motionTransitions, staggerContainer, staggerItem } from "@/lib/motion"

/**
 * Five top-level destinations, with the service routes gathered under one group rather than
 * competing for space in the bar. Everything a visitor arriving from search needs, what we do,
 * proof, writing, who we are, and the answers, is reachable in one interaction.
 */
const serviceLinks = [
  { href: "/services", label: "All services", description: "Every route in one place, from local growth to custom systems." },
  { href: "/local-growth", label: "Local growth", description: "Websites and search work for businesses selling in a place." },
  { href: "/custom-systems", label: "Custom systems", description: "Applications, portals, integrations and automation." },
  { href: "/enterprise", label: "Enterprise", description: "Bespoke platforms for complex operational and multi-site software." },
  { href: "/enterprise-websites", label: "Enterprise Websites", description: "Corporate websites and digital experiences for established organisations." },
  { href: "/enterprise/delivery", label: "Enterprise Delivery", description: "Discovery through production rollout for complex software engagements." },
  { href: "/security", label: "Security & Trust", description: "Architecture-led security, delivery controls and assurance posture." },
  { href: "/digital-growth-partnership", label: "Growth Partnership", description: "Ongoing, prioritised improvement after launch." },
  { href: "/services/business-growth-audit", label: "Business Growth Audit", description: "A prioritised roadmap before committing to a build." },
  { href: "/services/managed-business-email", label: "Managed Business Email", description: "Custom-domain mailboxes, configured and supported." },
  { href: "/pricing", label: "Pricing", description: "Published starting points, and how larger work is scoped." },
]

const PARTNER_CTA_CLASS = "bg-gradient-to-b from-[#ecd9a8] via-[#c8aa6e] to-[#a8884a] text-black shadow-[0_0_0_1px_rgba(219,193,142,.45),0_6px_18px_rgba(200,170,110,.18)] transition-[transform,box-shadow,filter] duration-200 hover:-translate-y-px hover:brightness-110 hover:shadow-[0_0_0_1px_rgba(236,217,168,.8),0_10px_26px_rgba(200,170,110,.32)] motion-reduce:transition-none motion-reduce:hover:translate-y-0 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#ecd9a8]"

const links = [
  { href: "/industries", label: "Industries" },
  { href: "/work", label: "Work" },
  { href: "/insights", label: "Insights" },
  { href: "/about", label: "About" },
  { href: "/faq", label: "FAQ" },
]

export function Nav() {
  const [scrolled, setScrolled] = useState(false)
  const [open, setOpen] = useState(false)
  const [servicesOpen, setServicesOpen] = useState(false)
  const [portalReady, setPortalReady] = useState(false)
  const pathname = usePathname()
  const reducedMotion = usePrefersReducedMotion()
  const toggleRef = useRef<HTMLButtonElement>(null)
  const panelRef = useRef<HTMLDivElement>(null)
  const servicesRef = useRef<HTMLDivElement>(null)
  const servicesTriggerRef = useRef<HTMLButtonElement>(null)
  const servicesMenuId = useId()

  useEffect(() => {
    setPortalReady(true)
  }, [])

  useEffect(() => {
    const handler = () => setScrolled(window.scrollY > 72)
    handler()
    window.addEventListener("scroll", handler, { passive: true })
    return () => window.removeEventListener("scroll", handler)
  }, [])

  useEffect(() => {
    setOpen(false)
    setServicesOpen(false)
  }, [pathname])

  // The services menu closes on Escape or on a click outside it, and returns focus to its trigger.
  useEffect(() => {
    if (!servicesOpen) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return
      setServicesOpen(false)
      servicesTriggerRef.current?.focus()
    }
    const onPointerDown = (event: MouseEvent) => {
      if (!servicesRef.current?.contains(event.target as Node)) setServicesOpen(false)
    }
    const onFocusIn = (event: FocusEvent) => {
      if (!servicesRef.current?.contains(event.target as Node)) setServicesOpen(false)
    }
    document.addEventListener("keydown", onKeyDown)
    document.addEventListener("mousedown", onPointerDown)
    document.addEventListener("focusin", onFocusIn)
    return () => {
      document.removeEventListener("keydown", onKeyDown)
      document.removeEventListener("mousedown", onPointerDown)
      document.removeEventListener("focusin", onFocusIn)
    }
  }, [servicesOpen])

  useEffect(() => {
    if (!open) return
    // Lock both html and body. Compensating padding prevents the classic
    // scrollbar-gutter jump on desktop-width viewports that still show the
    // mobile toggle below the `md` breakpoint (e.g. narrow browser windows).
    const html = document.documentElement
    const { body } = document
    const scrollbarGap = Math.max(0, window.innerWidth - html.clientWidth)
    const previous = {
      bodyOverflow: body.style.overflow,
      htmlOverflow: html.style.overflow,
      bodyPaddingRight: body.style.paddingRight,
    }
    body.style.overflow = "hidden"
    html.style.overflow = "hidden"
    if (scrollbarGap > 0) {
      body.style.paddingRight = `${scrollbarGap}px`
    }
    const panel = panelRef.current
    const focusable = panel?.querySelectorAll<HTMLElement>('a[href], button:not([disabled])') ?? []
    focusable[0]?.focus()

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false)
        toggleRef.current?.focus()
        return
      }
      if (event.key !== "Tab" || focusable.length === 0) return
      const first = focusable[0]
      const last = focusable[focusable.length - 1]
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }
    document.addEventListener("keydown", handleKeyDown)
    return () => {
      body.style.overflow = previous.bodyOverflow
      html.style.overflow = previous.htmlOverflow
      body.style.paddingRight = previous.bodyPaddingRight
      document.removeEventListener("keydown", handleKeyDown)
    }
  }, [open])

  const closeMenu = () => setOpen(false)
  const isActive = (href: string) => pathname === href || pathname.startsWith(`${href}/`)
  const servicesActive = serviceLinks.some((link) => isActive(link.href))
  const navOffset = scrolled ? "top-[62px]" : "top-[78px]"

  // Portal the drawer to `document.body`. The sticky header uses `backdrop-blur`,
  // which creates a containing block for `position: fixed` descendants. Leaving
  // the slide-in panel inside that header made the entire site translate left
  // with the drawer animation on mobile.
  const mobileMenu = portalReady
    ? createPortal(
        <AnimatePresence initial={false}>
          {open ? (
            <m.div
              key="mobile-nav-overlay"
              className={cn(
                "fixed inset-x-0 bottom-0 z-40 overflow-hidden overscroll-none bg-black/55 md:hidden",
                navOffset,
              )}
              initial={reducedMotion ? false : { opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: reducedMotion ? 0 : 0.18 }}
              onMouseDown={(event) => event.target === event.currentTarget && closeMenu()}
            >
              <m.div
                ref={panelRef}
                id="mobile-navigation"
                role="dialog"
                aria-modal="true"
                aria-label="Site navigation"
                className="ml-auto flex h-full w-[min(88vw,420px)] max-w-full flex-col overflow-y-auto overscroll-contain border-l border-b1 bg-bg px-7 pb-8 pt-8 shadow-2xl"
                initial={reducedMotion ? false : { x: "100%" }}
                animate={{ x: 0 }}
                exit={{ x: "100%" }}
                transition={reducedMotion ? { duration: 0 } : motionTransitions.gentle}
              >
                <m.div variants={staggerContainer} initial={reducedMotion ? false : "hidden"} animate="visible" className="flex flex-col">
                  <m.div variants={staggerItem} className="pb-4">
                    <Link href="/partners" prefetch={false} onClick={closeMenu} className={cn("inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-lg font-dm text-sm font-bold", PARTNER_CTA_CLASS)}>
                      <Handshake size={16} aria-hidden="true" /> Become a Partner
                    </Link>
                  </m.div>
                  {links.map((link) => (
                    <m.div key={link.href} variants={staggerItem}>
                      <Link href={link.href} prefetch={false} onClick={closeMenu} className="flex min-h-14 items-center border-b border-b1 font-syne text-xl font-bold text-t1">{link.label}</Link>
                    </m.div>
                  ))}
                  <m.p variants={staggerItem} className="pb-3 pt-7 font-dm text-[11px] font-semibold uppercase tracking-[.16em] text-t3">Services</m.p>
                  {serviceLinks.map((link) => (
                    <m.div key={link.href} variants={staggerItem}>
                      <Link href={link.href} prefetch={false} onClick={closeMenu} className="flex min-h-14 items-center border-b border-b1 font-syne text-lg font-bold text-t1">
                        {link.label}
                      </Link>
                    </m.div>
                  ))}
                </m.div>
                <div className="mt-auto grid gap-3 pt-8">
                  <Link href="/portal/login" prefetch={false} onClick={closeMenu} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-lg border border-b2 font-dm text-sm font-medium text-t1">
                    <LogIn size={15} className="text-acc" aria-hidden="true" /> Client Portal
                  </Link>
                  <Link href="/quote" prefetch={false} onClick={closeMenu} className="btn-sm min-h-12 justify-center">Start a Project</Link>
                </div>
              </m.div>
            </m.div>
          ) : null}
        </AnimatePresence>,
        document.body,
      )
    : null

  return (
    <header className={cn(
      "sticky top-0 z-50 border-b transition-[background-color,border-color,box-shadow] duration-300",
      scrolled ? "border-b1/80 bg-bg/94 shadow-[0_12px_40px_rgba(0,0,0,.22)] backdrop-blur-md" : "border-transparent bg-bg/45 backdrop-blur-sm",
    )}>
      <nav aria-label="Main navigation" className={cn(
        "relative z-50 mx-auto flex max-w-[1320px] items-center gap-6 px-6 lg:gap-10 transition-[height] duration-300 md:px-12",
        scrolled ? "h-[62px]" : "h-[78px]",
      )}>
        <Logo showName={false} size={scrolled ? 38 : 44} />

        <div className="ml-auto hidden items-center gap-3 md:flex lg:gap-7">
          <div
            ref={servicesRef}
            className="relative"
            onMouseEnter={() => setServicesOpen(true)}
            onMouseLeave={() => setServicesOpen(false)}
          >
            <button
              ref={servicesTriggerRef}
              type="button"
              onClick={() => setServicesOpen(true)}
              aria-expanded={servicesOpen}
              aria-controls={servicesMenuId}
              className={cn("group relative inline-flex items-center gap-1.5 py-2 font-dm text-[13px] font-medium tracking-[.01em]", servicesActive ? "text-t1" : "text-t2 hover:text-t1")}
            >
              Services
              <ChevronDown size={13} aria-hidden="true" className={cn("transition-transform", servicesOpen && "rotate-180")} />
              {servicesActive ? (
                <m.span layoutId="active-nav" className="absolute inset-x-0 -bottom-0.5 h-px bg-acc" transition={motionTransitions.ui} />
              ) : (
                <span className="absolute inset-x-0 -bottom-0.5 h-px origin-left scale-x-0 bg-t3 transition-transform duration-200 group-hover:scale-x-100" />
              )}
            </button>
            <AnimatePresence initial={false}>
              {servicesOpen ? (
                <m.div
                  id={servicesMenuId}
                  initial={reducedMotion ? false : { opacity: 0, y: -6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -6 }}
                  transition={{ duration: reducedMotion ? 0 : 0.16 }}
                  className="absolute left-1/2 top-full z-50 w-[min(92vw,600px)] -translate-x-1/2 pt-4"
                >
                  <ul className="grid gap-px overflow-hidden rounded-2xl border border-b1 bg-b1 shadow-[0_24px_60px_rgba(0,0,0,.35)] sm:grid-cols-2">
                    {serviceLinks.map((link) => (
                      <li key={link.href}>
                        <Link
                          href={link.href}
                          prefetch={false}
                          aria-current={isActive(link.href) ? "page" : undefined}
                          className="flex h-full flex-col bg-bg px-5 py-4 transition-colors hover:bg-s1"
                        >
                          <span className={cn("font-syne text-sm font-bold", isActive(link.href) ? "text-acc" : "text-t1")}>{link.label}</span>
                          <span className="mt-1 font-dm text-xs leading-relaxed text-t3">{link.description}</span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                </m.div>
              ) : null}
            </AnimatePresence>
          </div>

          {links.map((link) => {
            const active = isActive(link.href)
            return (
              <Link key={link.href} href={link.href} prefetch={false} aria-current={active ? "page" : undefined}
                className={cn("group relative py-2 font-dm text-[13px] font-medium tracking-[.01em]", active ? "text-t1" : "text-t2 hover:text-t1")}>
                {link.label}
                {active ? (
                  <m.span layoutId="active-nav" className="absolute inset-x-0 -bottom-0.5 h-px bg-acc" transition={motionTransitions.ui} />
                ) : (
                  <span className="absolute inset-x-0 -bottom-0.5 h-px origin-left scale-x-0 bg-t3 transition-transform duration-200 group-hover:scale-x-100" />
                )}
              </Link>
            )
          })}
          <Link href="/partners" prefetch={false} aria-current={isActive("/partners") ? "page" : undefined} className={cn("inline-flex min-h-9 items-center gap-1.5 whitespace-nowrap rounded-lg px-3 font-dm text-[12px] font-bold lg:px-4 lg:text-[13px]", PARTNER_CTA_CLASS)}>
            <Handshake size={14} aria-hidden="true" /> Become a Partner
          </Link>
          <Link href="/portal/login" prefetch={false} aria-label="Client Portal" className="group inline-flex min-h-9 items-center gap-2 border-l border-b1 pl-4 font-dm text-[13px] font-medium text-t2 transition-colors hover:text-t1 lg:pl-5">
            <LogIn size={14} className="text-acc" aria-hidden="true" />
            <span className="hidden lg:inline">Client Portal</span>
            <ArrowUpRight size={12} className="hidden text-t3 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5 lg:block" aria-hidden="true" />
          </Link>
          <Link href="/quote" prefetch={false} className="btn-sm group">
            Start a Project <ArrowUpRight size={13} className="transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" aria-hidden="true" />
          </Link>
        </div>

        <Link href="/partners" prefetch={false} aria-label="Become a Partner" className={cn("ml-auto inline-flex min-h-11 items-center gap-1.5 whitespace-nowrap rounded-lg px-3 font-dm text-[12px] font-bold md:hidden", PARTNER_CTA_CLASS)}>
          <Handshake size={14} aria-hidden="true" /> Partner
        </Link>
        <button ref={toggleRef} type="button" className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-lg border border-control bg-s1/70 text-t1 md:hidden"
          onClick={() => setOpen((value) => !value)} aria-label={open ? "Close menu" : "Open menu"} aria-expanded={open} aria-controls="mobile-navigation">
          {open ? <X size={20} aria-hidden="true" /> : <Menu size={20} aria-hidden="true" />}
        </button>
      </nav>

      {mobileMenu}
    </header>
  )
}

"use client"

import { useEffect } from "react"
import { captureGlobalRenderError, renderGlobalErrorFallback } from "./global-error-content"

export default function GlobalError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  useEffect(() => {
    captureGlobalRenderError(error)
  }, [error])

  return (
    <html lang="en">
      <body style={{ margin: 0, background: "#05070d", color: "#f5f7fa", fontFamily: "system-ui, sans-serif" }}>
        {renderGlobalErrorFallback(reset)}
      </body>
    </html>
  )
}

import type { Metadata } from "next"
import localFont from "next/font/local"
import { MotionProvider } from "@/components/MotionProvider"
import { SiteChrome } from "@/components/SiteChrome"
import { WebVitalsReporter } from "@/components/WebVitalsReporter"
import { CookiePreferences } from "@/components/CookiePreferences"
import { EnquiryAttributionCapture } from "@/components/EnquiryAttributionCapture"
import { GoogleAnalytics } from "@/components/GoogleAnalytics"
import { JsonLd } from "@/components/JsonLd"
import { siteBaseUrl } from "@/lib/site-identity"
import {
  buildOrganizationSchema,
  buildWebsiteSchema,
} from "@/lib/structured-data"
import "./globals.css"

const syne = localFont({
  src: "./fonts/Syne.woff2",
  variable: "--font-syne",
  display: "swap",
  weight: "400 800",
})

const siteUrl = siteBaseUrl()

export const metadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: {
    default: "ScaleSmiths | Digital Growth, Websites & Custom Systems",
    template: "%s | ScaleSmiths",
  },
  description:
    "ScaleSmiths helps ambitious businesses find growth constraints, build the right digital solution, and keep improving through websites, local growth, custom systems, automation and ongoing digital partnership.",
  keywords: [
    "growth partnership",
    "web development Nottingham",
    "web design Hucknall",
    "local business growth",
    "custom web app development UK",
    "e-commerce development",
    "Next.js agency",
    "digital infrastructure",
    "SEO agency Nottingham",
    "business automation consultancy",
  ],
  authors: [{ name: "ScaleSmiths" }],
  // Site-wide defaults only. Page titles, descriptions and URLs come from each route (see
  // lib/page-metadata.ts) so inner pages never inherit the homepage's social copy or URL.
  openGraph: {
    type: "website",
    locale: "en_GB",
    siteName: "ScaleSmiths",
  },
  twitter: {
    card: "summary_large_image",
  },
  robots: {
    index: true,
    follow: true,
    googleBot: { index: true, follow: true, "max-image-preview": "large" },
  },
  icons: {
    icon: [
      { url: "/brand/favicon.png", type: "image/png" },
    ],
  },
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en" className={syne.variable}>
      <head>
        <JsonLd
          data={[buildOrganizationSchema(siteUrl), buildWebsiteSchema(siteUrl)]}
        />
      </head>
      <body className="bg-bg text-t1 font-dm antialiased">
        <GoogleAnalytics />
        <EnquiryAttributionCapture />
        <WebVitalsReporter />
        <MotionProvider>
          <SiteChrome>{children}</SiteChrome>
          <CookiePreferences />
        </MotionProvider>
      </body>
    </html>
  )
}

