/* ── Design Tokens ─────────────────────────────────────────── */
:root {
  /* Dark forge identity (~70%) — charcoal + molten gold */
  --bg:     #0b0a08;
  --s1:     #141210;
  --s2:     #1c1915;
  --s3:     #26221c;
  --b1:     #3a342c;
  --b2:     #5c4f3d;
  --b3:     #8a7355;
  --t1:     #f5efe6;
  --t2:     #c9bdb0;
  --t3:     #95887a;
  --acc:    #e8a045;
  --acc-ink:#1a1208;
  --acc-dim:rgba(232,160,69,0.14);
  --acc-b:  rgba(232,160,69,0.30);
  --silver: #cfc7bc;
  --grn:    #14f1b2;
  --amb:    #fde68a;
  --red:    #ef4444;

  /* Paper relief (~30%) — warm ash daylight, forge-copper accent */
  --paper:         #d9d0c4;
  --paper-soft:    #ccc3b6;
  --paper-raised:  #e6dfd4;
  to { opacity: 1; transform: translateY(0); }
}

.float-anim {
  animation: float-soft 5.5s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .float-anim { animation: none; }
}

/* ── Hero element styles ─────────────────────────────────────── */
.hero-line-overflow {
  overflow: hidden;
  line-height: 1;
  width: 100%;
  max-width: 100%;
}

.hero-h {
  --hero-scale: 1;

@keyframes ember-flicker {
  0%, 100% { filter: brightness(1); }
  35% { filter: brightness(1.45); }
  65% { filter: brightness(0.8); }
}

@media (prefers-reduced-motion: reduce) {
  .hero-ember { animation: none; opacity: 0; }
  .hero-forge-video { display: none !important; }
}

@media (max-width: 767px) {
  .hero-forge-video { display: none !important; }
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  background: var(--acc);
  color: var(--acc-ink);
  font-weight: 600;
  padding: 14px 30px;
  border-radius: 10px;
  font-size: 15px;
  transition: opacity 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: 0 14px 36px rgba(232,160,69,0.18);
  text-decoration: none;
}
.btn-primary svg { transition: transform 0.2s ease; }
.btn-primary:hover { opacity: 0.96; transform: translateY(-1px); box-shadow: 0 16px 40px rgba(232,160,69,0.24); }
.btn-primary:hover svg { transform: translateX(3px); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--t1);
  border: 1px solid color-mix(in srgb, var(--acc) 26%, var(--b2));
  font-weight: 600;
  padding: 14px 30px;
  border-radius: 10px;
  font-size: 15px;
  transition: border-color 0.2s, background-color 0.2s, color 0.2s, box-shadow 0.2s;
  text-decoration: none;
}
.btn-ghost:hover {
  border-color: color-mix(in srgb, var(--acc) 52%, var(--b2));
  background: rgba(232, 160, 69, 0.07);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--acc) 16%, transparent);
}

.btn-sm {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  background: var(--acc);
  color: var(--acc-ink);
  font-weight: 600;
  padding: 9px 20px;
  border-radius: 9px;
  font-size: 14px;
  transition: opacity 0.2s;
  text-decoration: none;
}
.btn-sm:hover { opacity: 0.9; }

/* Light-surface button variants — forge copper on paper, not Bootstrap white */
.surface-paper .btn-primary {
  background: var(--paper-acc);
  color: #f8f4ef;
  box-shadow: 0 12px 28px rgba(122, 63, 18, 0.22);
}
.surface-paper .btn-ghost {
  background: rgba(11, 10, 8, 0.04);
  color: var(--paper-ink);
  border-color: var(--paper-border);
}
.surface-paper .btn-ghost:hover {
  border-color: var(--paper-acc);
  background: rgba(11, 10, 8, 0.07);
}

.v2-form-field {
  width: 100%;
  min-height: 46px;
  border-radius: 8px;
}
.card-lift:hover {
  transform: translateY(-4px);
  border-color: var(--b3) !important;
}

.footer-link {
  text-decoration-line: underline;
  text-decoration-color: transparent;
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
  transition: color 0.18s ease, text-decoration-color 0.18s ease;
}
