"use client"

import { ReactNode, useEffect } from "react"
import { usePathname } from "next/navigation"
import { Nav } from "@/components/Nav"
import { Footer } from "@/components/Footer"
import { trackExperienceEvent } from "@/lib/experience-analytics-client"
import { parseEnquiryIntent } from "@/lib/enquiry-intents"

interface SiteChromeProps {
  children: ReactNode
}

export function SiteChrome({ children }: SiteChromeProps) {
  const pathname = usePathname()
  const isInteractiveJourney = pathname === "/interactive"

  useEffect(() => {
    document.documentElement.dataset.scalesmithsHydrated = "true"
    return () => {
      delete document.documentElement.dataset.scalesmithsHydrated
    }
  }, [])

  useEffect(() => {
    function captureNavigation(event: MouseEvent) {
      const anchor = (event.target as Element | null)?.closest?.("a")
      const href = anchor?.getAttribute("href")
      if (!href) return
      if (href.startsWith("/quote")) {
        const intent = parseEnquiryIntent(new URL(href, window.location.origin).searchParams.get("intent"))
        trackExperienceEvent("quote_cta_clicked", { metadata: { source: `link:${pathname}`, target: href, intent } })
      }
      if (/^https?:\/\//.test(href) && !href.includes(window.location.hostname)) {
        trackExperienceEvent("navigation_exit", { metadata: { target: new URL(href).hostname } })
      }
    }

    document.addEventListener("click", captureNavigation, { capture: true })
    return () => document.removeEventListener("click", captureNavigation, { capture: true })
  }, [pathname])

  return (
    <>
      <a href="#main" className="skip-link sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-4 focus:z-50 focus:rounded-md focus:bg-acc focus:px-4 focus:py-2 focus:font-semibold focus:text-acc-ink">
        Skip to content
      </a>
      {!isInteractiveJourney && <Nav />}
      <main id="main" tabIndex={-1}>{children}</main>
      {!isInteractiveJourney && <Footer />}
    </>
  )
}
import { ArrowRight } from "lucide-react"
import { AnimateIn } from "./AnimateIn"
import { ProjectPlannerCta } from "@/components/ExperiencePreference"
import { Logo } from "./Logo"
import { MagneticLink } from "./MagneticLink"

export function CTA() {
  return (
    <section aria-label="Call to action" className="px-6 py-28 md:px-12">
      <AnimateIn className="relative mx-auto max-w-[760px] overflow-hidden rounded-3xl border border-acc/28 bg-gradient-to-br from-s2 via-s1 to-acc/[.1] px-8 py-[72px] text-center shadow-[0_28px_90px_rgba(232,160,69,0.1)] md:px-16">
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-acc/55 to-transparent"
        />
        <div
          aria-hidden="true"
          className="pointer-events-none absolute -bottom-20 left-1/2 h-48 w-[78%] -translate-x-1/2 rounded-full bg-acc/12 blur-3xl"
        />
        <div className="float-anim mb-8 inline-block" aria-hidden="true">
          <Logo size={52} showName={false} href="" />
        </div>
        <h2 className="mb-4 font-syne text-[clamp(28px,4.5vw,48px)] font-extrabold tracking-[-0.025em]">
          Discuss the next digital step with the people who would build it.
        </h2>
        <p className="mx-auto mb-10 max-w-[520px] font-dm text-base leading-relaxed text-t2">
          Tell us what is getting in the way. We will say whether the next step is a website, a Growth Partnership, a corporate digital transformation, a custom system, or something we should not sell you.
