import { expect, test } from "@playwright/test"

// Regression coverage for the public Scale Your Future entry points (checkpoint 1/2).
// These use the real header, footer, calculator and page; no applications are submitted.
const viewports = [[320, 800], [390, 844], [768, 1024], [1024, 768], [1440, 900]] as const

test.describe("partner programme public entry points", () => {
  for (const [width, height] of viewports) {
    test(`header, calculator and layout at ${width}px`, async ({ page }) => {
      await page.setViewportSize({ width, height })
      await page.goto("/partners")
      // Decline optional storage so the banner never covers controls.
      await page.getByRole("button", { name: /reject non-essential/i }).click({ timeout: 3000 }).catch(() => undefined)
      const cta = page.locator('header a[href="/partners"]:visible').first()
108:const MOBILE_MENU_VIEWPORTS = [
109-  { name: "galaxy-s8", width: 360, height: 740 },
110-  { name: "galaxy-s20", width: 360, height: 800 },
111-  { name: "iphone-12", width: 390, height: 844 },
112-  { name: "pixel-5", width: 393, height: 851 },
113-  { name: "samsung-a51", width: 412, height: 915 },
114-  { name: "android-430", width: 430, height: 932 },
  })

  test("desktop services menu is keyboard operable", async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 1000 })
    await setExperience(page, "normal")
    await rejectNonEssentialStorage(page)
    await visit(page, "/")

    const nav = page.getByRole("navigation", { name: /main navigation/i })
    const trigger = nav.getByRole("button", { name: "Services", exact: true })
    await trigger.focus()
    await page.keyboard.press("Enter")
    await expect(trigger).toHaveAttribute("aria-expanded", "true")
    await expect(nav.getByRole("link", { name: /^All services/ })).toBeVisible()
    await page.keyboard.press("Escape")
    await expect(trigger).toHaveAttribute("aria-expanded", "false")
  })

  test("FAQ disclosures work at every breakpoint", async ({ page }) => {
    await setExperience(page, "normal")
    await rejectNonEssentialStorage(page)

    for (const viewport of VIEWPORTS) {
      await page.setViewportSize({ width: viewport.width, height: viewport.height })
      await visit(page, "/faq")

      const first = page.locator("details#faq-cost")
      await expect(first, `${viewport.name}: closed by default`).not.toHaveAttribute("open", /.*/)
      await first.locator("summary").click()
      await expect(first, `${viewport.name}: opens on click`).toHaveAttribute("open", /.*/)
      await first.locator("summary").click()

